-- BiZ.lua: Mr.BiZ, best in slot per class / spec (ADDON_PLAN.md 19). Logic only; the
-- tab is UI/BiZ.lua, the data is BiZData.lua (generated by bis/build_bis.py from the
-- same files as the site's bis.html, so both show the same picks).
--
-- * Spec: R2FCharDB.biz.spec[classKey] = "class/spec" (the one last picked for that
--   class); the class shown is R2FCharDB.biz.class, the player's own class at first.
-- * Filters: R2FCharDB.biz.types[type] = false hides that source type (dungeon, world,
--   quest, crafted, vendor, reputation, pvp; raid once the data has raids);
--   R2FCharDB.biz.known = true hides picks whose source isn't known yet. Like the site,
--   a slot whose best pick is filtered out stays in the list, marked as hidden.
-- * Wishlist: R2FCharDB.biz.wish[itemId] = { spec = "class/spec", slot = "head" }, per
--   character (the site keeps one per character name too). Export / Import use the
--   site's string: R2FW1:<id>:<class/spec>:<slot>,...
-- * Items: names come from the data; quality, icon and the tooltip come from the game.
--   An item the client hasn't cached yet shows white with a question-mark icon until
--   GET_ITEM_INFO_RECEIVED (Core.lua) redraws the tab.
--
-- Read-only game-wise (item getters, the tooltip): everything works in combat.

local _, R2F = ...

local BiZ = {}
R2F.BiZ = BiZ

local WISH_PREFIX = "R2FW1:"

-- In-game item quality colours (0 poor .. 5 legendary); used when the client's
-- ITEM_QUALITY_COLORS table isn't there.
local QUALITY_HEX = { [0] = "9d9d9d", "ffffff", "1eff00", "0070dd", "a335ee", "ff8000" }
local CLASS_TOKEN = {
  PRIEST = "priest", WARLOCK = "warlock", MAGE = "mage", ROGUE = "rogue", DRUID = "druid",
  SHAMAN = "shaman", HUNTER = "hunter", PALADIN = "paladin", WARRIOR = "warrior",
}

local function data() return R2F.BiZData end
local function cdb() return R2F.Library.cdb.biz end

-- ---------------------------------------------------------------------------
-- Class and spec
-- ---------------------------------------------------------------------------

function BiZ.Classes() return data().classes end

local function classDef(key)
  for _, c in ipairs(data().classes) do
    if c.key == key then return c end
  end
end

function BiZ.ClassName(key)
  local c = classDef(key)
  return c and c.name or key
end

function BiZ.PlayerClassKey()
  local token = R2F.playerClass or select(2, UnitClass("player"))
  return CLASS_TOKEN[token or ""] or "warrior"
end

-- The class being looked at (the player's own until another is picked).
function BiZ.Class()
  local key = cdb().class
  if not classDef(key) then key = BiZ.PlayerClassKey() end
  return key
end

function BiZ.SetClass(key)
  if classDef(key) then cdb().class = key end
end

function BiZ.SpecsOf(classKey)
  local c = classDef(classKey)
  return c and c.specs or {}
end

function BiZ.Spec(specId)
  return data().specs[specId]
end

-- The spec id shown for the current class: the one picked last for it, else its first.
function BiZ.SpecId()
  local cls = BiZ.Class()
  local id = cdb().spec[cls]
  if not (id and data().specs[id] and data().specs[id].class == cls) then id = BiZ.SpecsOf(cls)[1] end
  return id
end

function BiZ.SetSpec(specId)
  local s = data().specs[specId]
  if s then
    cdb().class = s.class
    cdb().spec[s.class] = specId
  end
end

function BiZ.SlotLabel(key)
  for _, s in ipairs(data().slots) do
    if s.key == key then return s.label end
  end
  return key
end

-- ---------------------------------------------------------------------------
-- Filters
-- ---------------------------------------------------------------------------

-- The source types that occur in the data, in chip order (raid only once there is any).
function BiZ.Types()
  local present = {}
  for _, sp in pairs(data().specs) do
    for _, sl in ipairs(sp.slots) do
      if sl.best then present[sl.best.type] = true end
    end
  end
  local out = {}
  for _, t in ipairs(data().types) do
    if present[t] then out[#out + 1] = t end
  end
  return out
end

function BiZ.TypeOn(t) return cdb().types[t] ~= false end
-- Off is stored as false; on clears the key (on is the default).
function BiZ.SetTypeOn(t, on)
  if on then cdb().types[t] = nil else cdb().types[t] = false end
end
function BiZ.KnownOnly() return cdb().known == true end
function BiZ.SetKnownOnly(on) cdb().known = on and true or false end

function BiZ.Passes(best)
  if best.type ~= "unknown" and cdb().types[best.type] == false then return false end
  if cdb().known and best.type == "unknown" then return false end
  return true
end

-- "Horde only" / "Alliance only" when the pick is the other faction's (a faction quest),
-- nil otherwise.
function BiZ.FactionNote(best)
  if not best.faction then return nil end
  local mine = (UnitFactionGroup and UnitFactionGroup("player")) or "Alliance"
  if best.faction ~= mine:lower() then
    return best.faction == "horde" and R2F.L.BIZ_HORDE_ONLY or R2F.L.BIZ_ALLIANCE_ONLY
  end
end

-- ---------------------------------------------------------------------------
-- Wishlist
-- ---------------------------------------------------------------------------

function BiZ.IsWished(id) return cdb().wish[id] ~= nil end

function BiZ.ToggleWish(id, specId, slot)
  if cdb().wish[id] then
    cdb().wish[id] = nil
  else
    cdb().wish[id] = { spec = specId, slot = slot }
  end
end

function BiZ.WishCount()
  local n = 0
  for _ in pairs(cdb().wish) do n = n + 1 end
  return n
end

-- id -> { name, group, label } from every spec's best picks, and names of the next picks.
local index
local function itemIndex()
  if index then return index end
  index = {}
  for _, sp in pairs(data().specs) do
    for _, sl in ipairs(sp.slots) do
      if sl.best then
        index[sl.best.id] = { name = sl.best.name, group = sl.best.group, label = sl.best.label }
      end
    end
  end
  for _, sp in pairs(data().specs) do
    for _, sl in ipairs(sp.slots) do
      for _, n in ipairs(sl.next or {}) do
        if not index[n.id] then index[n.id] = { name = n.name } end
      end
    end
  end
  return index
end

function BiZ.ItemName(id)
  local i = itemIndex()[id]
  return (i and i.name) or ((GetItemInfo and GetItemInfo(id)) or ("item " .. id))
end

-- { { name = group, items = { { id, name, label, spec, slot }, ... } }, ... }, the biggest
-- group first (that's where a trip gets the most done), then by name. Items with no known
-- source (a next-best pick) share one group at the end.
function BiZ.WishGroups()
  local byName, order = {}, {}
  for id, w in pairs(cdb().wish) do
    local info = itemIndex()[id] or {}
    local g = info.group or R2F.L.BIZ_GROUP_NEXT
    if not byName[g] then byName[g] = {}; order[#order + 1] = g end
    table.insert(byName[g], { id = id, name = BiZ.ItemName(id), label = info.label, spec = w.spec, slot = w.slot })
  end
  table.sort(order, function(a, b)
    if a == R2F.L.BIZ_GROUP_NEXT then return false end
    if b == R2F.L.BIZ_GROUP_NEXT then return true end
    if #byName[a] ~= #byName[b] then return #byName[a] > #byName[b] end
    return a < b
  end)
  local out = {}
  for _, g in ipairs(order) do
    table.sort(byName[g], function(x, y) return x.name < y.name end)
    out[#out + 1] = { name = g, items = byName[g] }
  end
  return out
end

function BiZ.Export()
  local ids = {}
  for id in pairs(cdb().wish) do ids[#ids + 1] = id end
  table.sort(ids)
  local parts = {}
  for _, id in ipairs(ids) do
    local w = cdb().wish[id]
    parts[#parts + 1] = id .. ":" .. (w.spec or "") .. ":" .. (w.slot or "")
  end
  return WISH_PREFIX .. table.concat(parts, ",")
end

-- Adds the string's items to the wishlist. Returns the number of new items, or nil and
-- an error message if the text isn't a wishlist string.
function BiZ.Import(text)
  local body = (text or ""):match("R2FW1:(%S*)")
  if not body then return nil, R2F.L.BIZ_IMPORT_BAD end
  local added = 0
  for part in body:gmatch("[^,]+") do
    local id, spec, slot = part:match("^(%d+):([%w%-]+/[%w%-]+):?([%w]*)$")
    id = tonumber(id)
    if id and data().specs[spec] then
      if not cdb().wish[id] then added = added + 1 end
      cdb().wish[id] = { spec = spec, slot = slot ~= "" and slot or nil }
    end
  end
  return added
end

-- ---------------------------------------------------------------------------
-- Items in the game client
-- ---------------------------------------------------------------------------

-- Quality 0-5, or nil while the client hasn't loaded the item (asks it to).
function BiZ.Quality(id)
  local q
  if C_Item and C_Item.GetItemQualityByID then q = C_Item.GetItemQualityByID(id) end
  if q == nil and GetItemInfo then q = select(3, GetItemInfo(id)) end
  if q == nil and C_Item and C_Item.RequestLoadItemDataByID then C_Item.RequestLoadItemDataByID(id) end
  return q
end

-- "|cffRRGGBBname|r" in the item's quality colour (white until it's known).
function BiZ.ColoredName(id, name)
  local q = BiZ.Quality(id)
  local hex = q and QUALITY_HEX[q]
  local c = q and ITEM_QUALITY_COLORS and ITEM_QUALITY_COLORS[q]
  if c and c.hex then return c.hex .. name .. "|r" end
  return "|cff" .. (hex or "ffffff") .. name .. "|r"
end

function BiZ.Icon(id)
  local icon
  if C_Item and C_Item.GetItemIconByID then icon = C_Item.GetItemIconByID(id) end
  if not icon and GetItemIcon then icon = GetItemIcon(id) end
  if not icon and GetItemInfoInstant then icon = select(5, GetItemInfoInstant(id)) end
  return icon
end

-- The game's own item tooltip on `owner`, plus Mr.BiZ's line (rank in the spec shown).
function BiZ.ShowTooltip(owner, id, rankLine)
  GameTooltip:SetOwner(owner, "ANCHOR_RIGHT")
  if GameTooltip.SetItemByID then
    GameTooltip:SetItemByID(id)
  else
    GameTooltip:SetHyperlink("item:" .. id)
  end
  if rankLine then
    GameTooltip:AddLine(" ")
    GameTooltip:AddLine(rankLine, 1, 0.82, 0, true)
  end
  GameTooltip:Show()
end

-- Shift-click: the item's link in the chat box (like clicking a bag item).
function BiZ.LinkInChat(id)
  local link = GetItemInfo and select(2, GetItemInfo(id))
  if link and ChatEdit_InsertLink then ChatEdit_InsertLink(link) end
  return link ~= nil
end
